<?php $title='Event Management';require dirname(__DIR__).'/layouts/header.php';?><div class="page-heading"><div class="eyebrow">ADMINISTRATION</div><h1>Event moderation</h1><p>Review submitted events and control publication status.</p></div><div class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>Event</th><th>Organizer</th><th>Date</th><th>Status</th><th>Moderation</th></tr></thead><tbody><?php foreach($events as $ev):?><tr><td><b><?=e($ev['title'])?></b><small class="block muted"><?=e($ev['city'])?></small></td><td><?=e($ev['organizer_name'])?></td><td><?=e(date('d M Y',strtotime($ev['start_date'])))?></td><td><span class="status-pill"><?=e($ev['status'])?></span></td><td><form method="post" class="moderate-form"><?=csrf_field()?><input type="hidden" name="id" value="<?=$ev['id']?>"><select name="status"><option value="published">Publish</option><option value="rejected">Reject</option><option value="cancelled">Cancel</option></select><button class="btn btn-small">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php require dirname(__DIR__).'/layouts/footer.php';?>